    "category": "\u10DA\u10D0\u10D8\u10D5\u10F0\u10D0\u10D9\u10D8",
    "content": "\u10E1\u10D0\u10EE\u10DA\u10E8\u10D8 \u10DE\u10D8\u10E0\u10D5\u10D4\u10DA\u10D0\u10D3\u10D8 \u10D3\u10D0\u10EE\u10DB\u10D0\u10E0\u10D4\u10D1\u10D8\u10E1 \u10DC\u10D8\u10D5\u10D7\u10D4\u10D1\u10D8 \u10D4\u10E0\u10D7 \u10D0\u10D3\u10D2\u10D8\u10DA\u10D0\u10E1 \u10E8\u10D4\u10D8\u10DC\u10D0\u10EE\u10D4 \u2014 \u10E1\u10D0\u10ED\u10D8\u10E0\u10DD\u10D4\u10D1\u10D8\u10E1\u10D0\u10E1 \u10EB\u10D4\u10D1\u10DC\u10D0\u10E8\u10D8 \u10D3\u10E0\u10DD\u10E1 \u10D0\u10E0 \u10D3\u10D0\u10D9\u10D0\u10E0\u10D2\u10D0\u10D5.",
