    "content": "\u201E\u10D1\u10D4\u10D3\u10DC\u10D8\u10D4\u10E0\u10D4\u10D1\u10D0 \u10E8\u10D8\u10DC\u10D0\u10D2\u10D0\u10DC\u10D8 \u10DB\u10D3\u10D2\u10DD\u10DB\u10D0\u10E0\u10D4\u10DD\u10D1\u10D0\u10D0 \u10D3\u10D0 \u10D0\u10E0\u10D0 \u10D2\u10D0\u10E0\u10D4 \u10DE\u10D8\u10E0\u10DD\u10D1\u10D4\u10D1\u10D8\u10E1 \u10E8\u10D4\u10D3\u10D4\u10D2\u10D8.\u201C",
