    "content": "\u201E\u10E1\u10D8\u10D1\u10E0\u10EB\u10DC\u10D4 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10D0\u10E0\u10D8\u10E1 \u10D8\u10DB\u10D8\u10E1 \u10EA\u10DD\u10D3\u10DC\u10D0, \u10E0\u10DD\u10D3\u10D8\u10E1 \u10E3\u10DC\u10D3\u10D0 \u10D2\u10D0\u10E9\u10E3\u10DB\u10D3\u10D4.\u201C",
