    "content": "\u10EB\u10E0\u10D0\u10D5\u10D8\u10E1 \u10DB\u10E3\u10E8\u10D0\u10DD\u10D1\u10D8\u10E1\u10D0\u10E1 \u10E3\u10EA\u10DC\u10D0\u10E3\u10E0\u10D8 \u10E1\u10E3\u10DC\u10D8 \u10D7\u10E3 \u10D8\u10D2\u10E0\u10EB\u10D4\u10DC\u10D8, \u10DB\u10D8\u10D6\u10D4\u10D6\u10D8 \u10D3\u10E0\u10DD\u10E3\u10DA\u10D0\u10D3 \u10D2\u10D0\u10D0\u10E0\u10D9\u10D5\u10D8\u10D4.",
