    "content": "\u201E\u10D0\u10D3\u10D0\u10DB\u10D8\u10D0\u10DC\u10D8\u10E1 \u10EE\u10D0\u10E1\u10D8\u10D0\u10D7\u10D8 \u10DB\u10D8\u10E1\u10D8 \u10D1\u10D4\u10D3\u10D8\u10D0.\u201C \u2014 \u10F0\u10D4\u10E0\u10D0\u10D9\u10DA\u10D8\u10E2\u10D4",
