    "content": "\u201E\u10E3\u10D1\u10E0\u10D0\u10DA\u10DD\u10D3 \u10E7\u10DD\u10E4\u10DC\u10D0 \u10D0\u10D3\u10D5\u10D8\u10DA\u10D8\u10D0; \u10DB\u10DC\u10D8\u10E8\u10D5\u10DC\u10D4\u10DA\u10DD\u10D5\u10DC\u10D0\u10D3 \u10EA\u10EE\u10DD\u10D5\u10E0\u10D4\u10D1\u10D0 \u2014 \u10E0\u10D7\u10E3\u10DA\u10D8.\u201C",
