    "content": "\u201E\u10EA\u10EE\u10DD\u10D5\u10E0\u10D4\u10D1\u10D0 \u10D0\u10E0 \u10D0\u10E0\u10D8\u10E1 \u10DE\u10E0\u10DD\u10D1\u10DA\u10D4\u10DB\u10D4\u10D1\u10D8\u10E1 \u10D0\u10E0\u10E5\u10DD\u10DC\u10D0; \u10EA\u10EE\u10DD\u10D5\u10E0\u10D4\u10D1\u10D0\u10D0 \u10DB\u10D0\u10D7\u10D8 \u10D2\u10D0\u10D3\u10D0\u10ED\u10E0\u10D8\u10E1 \u10E3\u10DC\u10D0\u10E0\u10D8.\u201C",
