    "content": "\u10E2\u10D0\u10DC\u10E1\u10D0\u10EA\u10DB\u10D4\u10DA\u10D8 \u10E1\u10D0\u10E6\u10D0\u10DB\u10DD\u10E1 \u10DB\u10DD\u10D0\u10DB\u10D6\u10D0\u10D3\u10D4 \u2014 \u10D3\u10D8\u10DA\u10D0 \u10DB\u10E8\u10D5\u10D8\u10D3\u10D0\u10D3 \u10D3\u10D0\u10D8\u10EC\u10E7\u10D4\u10D1\u10D0.",
