    "content": "\u201E\u10DB\u10DD\u10D7\u10DB\u10D8\u10DC\u10D4\u10D1\u10D0 \u10DB\u10EC\u10D0\u10E0\u10D4\u10D0, \u10DB\u10D0\u10D2\u10E0\u10D0\u10DB \u10DB\u10D8\u10E1\u10D8 \u10DC\u10D0\u10E7\u10DD\u10E4\u10D8 \u10E2\u10D9\u10D1\u10D8\u10DA\u10D8\u10D0.\u201C \u2014 \u10D0\u10E0\u10D8\u10E1\u10E2\u10DD\u10E2\u10D4\u10DA\u10D4",
