    "content": "\u10D6\u10D0\u10DB\u10D7\u10D0\u10E0\u10E8\u10D8 \u10E1\u10E3\u10E1\u10E2\u10D8 \u10D0\u10D9\u10E3\u10DB\u10E3\u10DA\u10D0\u10E2\u10DD\u10E0\u10D8 \u10EC\u10D8\u10DC\u10D0\u10E1\u10EC\u10D0\u10E0 \u10E8\u10D4\u10D0\u10DB\u10DD\u10EC\u10DB\u10D4 \u2014 \u10E1\u10D8\u10EA\u10D8\u10D5\u10D4 \u10DB\u10D8\u10E1 \u10E8\u10D4\u10E1\u10D0\u10EB\u10DA\u10D4\u10D1\u10DA\u10DD\u10D1\u10D4\u10D1\u10E1 \u10D0\u10DB\u10EA\u10D8\u10E0\u10D4\u10D1\u10E1.",
