    "category": "\u10EA\u10D8\u10E2\u10D0\u10E2\u10D0",
    "content": "\u201E\u10E7\u10D5\u10D4\u10DA\u10D0 \u10D3\u10D0\u10E1\u10D0\u10E1\u10E0\u10E3\u10DA\u10D8 \u10D0\u10EE\u10D0\u10DA\u10D8 \u10D3\u10D0\u10E1\u10D0\u10EC\u10E7\u10D8\u10E1\u10D8\u10E1 \u10E8\u10D4\u10E1\u10D0\u10EB\u10DA\u10D4\u10D1\u10DA\u10DD\u10D1\u10D0\u10E1 \u10E8\u10D4\u10D8\u10EA\u10D0\u10D5\u10E1.\u201C",
