    "category": "\u10EA\u10D8\u10E2\u10D0\u10E2\u10D0",
    "content": "\u201E\u10DC\u10D0\u10DB\u10D3\u10D5\u10D8\u10DA\u10D8 \u10D7\u10D0\u10D5\u10D8\u10E1\u10E3\u10E4\u10DA\u10D4\u10D1\u10D0 \u10D0\u10E0\u10E9\u10D4\u10D5\u10D0\u10DC\u10D8\u10E1 \u10E5\u10DD\u10DC\u10D0\u10D0, \u10EE\u10DD\u10DA\u10DD \u10DC\u10D0\u10DB\u10D3\u10D5\u10D8\u10DA\u10D8 \u10E1\u10D8\u10D1\u10E0\u10EB\u10DC\u10D4 \u2014 \u10E1\u10EC\u10DD\u10E0\u10D8 \u10D0\u10E0\u10E9\u10D4\u10D5\u10D0\u10DC\u10D8\u10E1.\u201C",
